package com.turfly;
import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.Bean; import org.springframework.beans.factory.annotation.Value; import java.math.BigDecimal; import java.time.*; import java.util.*;
record RegisterRequest(@NotBlank String name,@Email @NotBlank String email,String phone,@NotBlank @Size(min=8) String password){} record LoginRequest(@Email @NotBlank String email,@NotBlank String password){} record TurfRequest(@NotBlank String name,@NotBlank String location,@NotBlank String sport,String description,@NotNull @DecimalMin("0.01") BigDecimal pricePerHour,String imageUrl,TurfStatus status){} record BookingRequest(@NotNull Long turfId,@NotNull LocalDate date,@NotNull LocalTime startTime,@NotNull LocalTime endTime){}
@RestController @RequestMapping("/api/auth") class AuthController {
 final UserRepository users;final PasswordEncoder encoder;final JwtService jwt;AuthController(UserRepository u,PasswordEncoder e,JwtService j){users=u;encoder=e;jwt=j;}
 @PostMapping("/register") Map<String,Object> register(@Valid @RequestBody RegisterRequest r){if(users.existsByEmail(r.email().toLowerCase()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Email already registered");AppUser u=new AppUser(r.name(),r.email().toLowerCase(),r.phone(),encoder.encode(r.password()),Role.CUSTOMER);users.save(u);return Map.of("token",jwt.create(u),"user",view(u));}
 @PostMapping("/login") Map<String,Object> login(@Valid @RequestBody LoginRequest r){AppUser u=users.findByEmail(r.email().toLowerCase()).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid email or password"));if(!encoder.matches(r.password(),u.password))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid email or password");return Map.of("token",jwt.create(u),"user",view(u));}
 static Map<String,Object> view(AppUser u){return Map.of("id",u.id,"name",u.name,"email",u.email,"phone",u.phone==null?"":u.phone,"role",u.role.name());}
}
@RestController @RequestMapping("/api/turfs") class TurfController {
 final TurfRepository turfs;final BookingRepository bookings;TurfController(TurfRepository t,BookingRepository b){turfs=t;bookings=b;}
 @GetMapping List<Turf> list(@RequestParam(required=false) String q,@RequestParam(required=false) String sport){return turfs.search(q==null||q.isBlank()?null:q,sport==null||sport.isBlank()?null:sport);}
 @GetMapping("/{id}") Turf get(@PathVariable Long id){return turfs.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));}
 @GetMapping("/{id}/availability") Map<String,Object> available(@PathVariable Long id,@RequestParam LocalDate date,@RequestParam LocalTime startTime,@RequestParam LocalTime endTime){validateSlot(date,startTime,endTime);if(!turfs.existsById(id))throw new ResponseStatusException(HttpStatus.NOT_FOUND);return Map.of("available",!bookings.overlaps(id,date,startTime,endTime));}
 static void validateSlot(LocalDate d,LocalTime s,LocalTime e){if(d.isBefore(LocalDate.now())||d.equals(LocalDate.now())&&!s.isAfter(LocalTime.now())||!s.isBefore(e)||Duration.between(s,e).toMinutes()<30||Duration.between(s,e).toMinutes()>720)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Choose a future time and a valid 30 minute to 12 hour time range");}
}
@RestController @RequestMapping("/api/bookings") class BookingController {
 final BookingRepository bookings;final TurfRepository turfs;final UserRepository users;BookingController(BookingRepository b,TurfRepository t,UserRepository u){bookings=b;turfs=t;users=u;}
 AppUser current(Authentication a){return users.findByEmail(a.getName()).orElseThrow();}
 @Transactional @PostMapping Booking create(@Valid @RequestBody BookingRequest r,Authentication a){TurfController.validateSlot(r.date(),r.startTime(),r.endTime());Turf turf=turfs.lockById(r.turfId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Turf not found"));if(turf.status!=TurfStatus.ACTIVE)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Turf is unavailable");if(bookings.overlaps(turf.id,r.date(),r.startTime(),r.endTime()))throw new ResponseStatusException(HttpStatus.CONFLICT,"That slot has just been booked");BigDecimal hours=BigDecimal.valueOf(Duration.between(r.startTime(),r.endTime()).toMinutes()).divide(BigDecimal.valueOf(60),2,java.math.RoundingMode.HALF_UP);Booking b=new Booking();b.user=current(a);b.turf=turf;b.date=r.date();b.startTime=r.startTime();b.endTime=r.endTime();b.amount=turf.pricePerHour.multiply(hours);return bookings.save(b);}
 @GetMapping("/mine") List<Map<String,Object>> mine(Authentication a){return bookings.findByUserIdOrderByCreatedAtDesc(current(a).id).stream().map(this::view).toList();}
 @PatchMapping("/{id}/cancel") @Transactional Map<String,Object> cancel(@PathVariable Long id,Authentication a){Booking b=bookings.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));AppUser u=current(a);if(!b.user.id.equals(u.id)&&u.role!=Role.ADMIN)throw new ResponseStatusException(HttpStatus.FORBIDDEN);if(b.status==BookingStatus.CANCELLED)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Booking is already cancelled");if(b.date.isBefore(LocalDate.now())||b.date.equals(LocalDate.now())&&!b.startTime.isAfter(LocalTime.now()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"This booking can no longer be cancelled");b.status=BookingStatus.CANCELLED;b.paymentStatus=PaymentStatus.REFUNDED;return view(bookings.save(b));}
 Map<String,Object> view(Booking b){return Map.ofEntries(Map.entry("id",b.id),Map.entry("userId",b.user.id),Map.entry("userName",b.user.name),Map.entry("turfId",b.turf.id),Map.entry("turfName",b.turf.name),Map.entry("location",b.turf.location),Map.entry("sport",b.turf.sport),Map.entry("date",b.date),Map.entry("startTime",b.startTime),Map.entry("endTime",b.endTime),Map.entry("amount",b.amount),Map.entry("status",b.status),Map.entry("paymentStatus",b.paymentStatus),Map.entry("createdAt",b.createdAt));}
}
